```json
{
  "name": "produce_and_execute_r",
  "arguments": {
    "rscript": "
# Load required packages
library(readr)
library(dplyr)
library(tidyr)
library(purrr)

# Load metadata and file names
metadata <- list(
  'wave_one_lsype_young_person_2020.tab' = list(
    file = 'data/input/wave_one_lsype_young_person_2020.tab',
    age = 14,
    ever_var = 'W1alceverYP',
    freq_var = 'W1alcmonYP',
    special_rule = TRUE
  ),
  'wave_two_lsype_young_person_2020.tab' = list(
    file = 'data/input/wave_two_lsype_young_person_2020.tab',
    age = 15,
    ever_var = 'W2alceverYP',
    freq_var = 'W2alcfreqYP',
    special_rule = FALSE
  ),
  'wave_three_lsype_young_person_2020.tab' = list(
    file = 'data/input/wave_three_lsype_young_person_2020.tab',
    age = 16,
    ever_var = 'W3alceverYP',
    freq_var = 'W3alcfreqYP',
    special_rule = FALSE
  ),
  'wave_four_lsype_young_person_2020.tab' = list(
    file = 'data/input/wave_four_lsype_young_person_2020.tab',
    age = 17,
    ever_var = 'W4AlcEverYP',
    freq_var = 'W4AlcFreqYP',
    special_rule = FALSE
  ),
  'wave_six_lsype_young_person_2020.tab' = list(
    file = 'data/input/wave_six_lsype_young_person_2020.tab',
    age = 19,
    ever_var = 'W6AlcEverYP',
    freq_var = 'W6AlcFreqYP',
    special_rule = FALSE
  ),
  'wave_seven_lsype_young_person_2020.tab' = list(
    file = 'data/input/wave_seven_lsype_young_person_2020.tab',
    age = 20,
    ever_var = 'W7AlcEverYP',
    freq_var = 'W7AlcFreqYP',
    special_rule = FALSE
  ),
  'ns8_2015_self_completion.tab' = list(
    file = 'data/input/ns8_2015_self_completion.tab',
    age = 25,
    ever_var = 'W8AUDIT1',
    freq_var = NULL,
    special_rule = FALSE
  ),
  'ns9_2022_main_interview.tab' = list(
    file = 'data/input/ns9_2022_main_interview.tab',
    age = 32,
    ever_var = 'W9AUDIT1',
    freq_var = NULL,
    special_rule = FALSE
  )
)

# Load all datasets and merge by NSID
load_and_merge_data <- function() {
  files <- imap(metadata, ~ read_delim(.y$file, delim = '\\t'))

  # Merge all datasets by NSID
  merged_data <- files[[1]]
  for (i in 2:length(files)) {
    merged_data <- full_join(merged_data, files[[i]], by = 'NSID')
  }

  return(merged_data)
}

# Function to map missing values to standard codes
map_missing_values <- function(x) {
  if (is.numeric(x)) {
    x <- ifelse(x >= -999 & x <= -1, recode_missing_values(x), x)
  }
  return(x)
}

# Recode missing values to standard scheme
recode_missing_values <- function(x) {
  x <- ifelse(
    x %in% c(-999, -998, -997, -995, -99, -96, -92, -91, -1),
    recode(
      x,
      `-999` = -2, `-998` = -2, `-997` = -2, `-995` = -2,
      `-99` = -3, `-97` = -2, `-96` = -2, `-92` = -9,
      `-91` = -1, `-1` = -8
    ),
    x
  )
  return(x)
}

# Function to determine drinking status for each sweep
determine_drinking_status <- function(df) {
  # Create a list of drinking status variables
  drinking_status <- list()

  for (i in seq_along(metadata)) {
    file_info <- metadata[[i]]
    age <- file_info$age
    ever_var <- file_info$ever_var
    freq_var <- file_info$freq_var
    special_rule <- file_info$special_rule

    # Handle special rule for sweep 1
    if (special_rule) {
      df <- df %>%
        mutate(
          `drinking_${age}` = ifelse(
            `W1alceverYP` == 1 & `W1alcmonYP` == 1,
            1,
            ifelse(`W1alceverYP` == 1, 0, NA_real_)
          )
        )
    } else {
      # For sweeps 2-4, 6-7, use ever_var
      if (age %in% c(15, 16, 17, 19, 20)) {
        df <- df %>%
          mutate(`drinking_${age}` = ifelse(`{{ever_var}}` == 1, 1, NA_real_))
      }
      # For sweeps 8-9, use AUDIT frequency (above 'Never')
      if (age %in% c(25, 32)) {
        df <- df %>%
          mutate(`drinking_${age}` = ifelse(`{{ever_var}}` > 1, 1, NA_real_))
      }
    }
  }

  return(df)
}

# Function to derive alcfst variable
derive_alcfst <- function(df) {
  ages <- c(14, 15, 16, 17, 19, 20, 25, 32)
  drinking_vars <- paste0('drinking_', ages)

  # Check which drinking variables are available
  available_vars <- drinking_vars[df %>% select(all_of(drinking_vars)) %>% select_if(any_vars) %>% names()]

  # Initialize alcfst with NA
  df <- df %>%
    mutate(alcfst = NA_integer_)

  # Determine earliest age of drinking
  for (age in ages) {
    var_name <- paste0('drinking_', age)
    if (var_name %in% available_vars) {
      df <- df %>%
        mutate(alcfst = ifelse(
          is.na(alcfst) & !is.na(`{{var_name}}`) & `{{var_name}}` == 1,
          age,
          alcfst
        ))
    }
  }

  # Handle cases where no drinking is observed
  df <- df %>%
    mutate(
      alcfst = ifelse(
        is.na(alcfst) & !any(sapply(drinking_vars, function(x) !is.na(df[[x]]) & df[[x]] == 1)),
        ifelse(all(sapply(drinking_vars, function(x) !is.na(df[[x]]))), 99, -8),
        alcfst
      )
    )

  # Convert to factor with appropriate levels and labels
  df$alcfst <- factor(
    df$alcfst,
    levels = c(14, 15, 16, 17, 19, 20, 25, 32, 99, -8),
    labels = c(
      'Age 14', 'Age 15', 'Age 16', 'Age 17', 'Age 19', 'Age 20',
      'Age 25', 'Age 32', 'Never had alcohol', 'Don\'t know/insufficient information'
    )
  )

  return(df)
}

# Main execution
merged_data <- load_and_merge_data()

# Map missing values to standard codes
for (var in names(merged_data)) {
  if (is.numeric(merged_data[[var]])) {
    merged_data[[var]] <- recode_missing_values(merged_data[[var]])
  }
}

# Determine drinking status for each sweep
merged_data <- determine_drinking_status(merged_data)

# Derive alcfst variable
final_data <- derive_alcfst(merged_data)

# Select only NSID and alcfst for output
output_data <- final_data %>% select(NSID, alcfst)

# Write output to CSV
write_csv(output_data, 'data/output/cleaned_data.csv')
"
  }
}
