  for (i in 2:length(files)) {
    merged_data <- full_join(merged_data, files[[i]], by = 'NSID')
  }

  return(merged_data)
}

# Function to map missing values to standard codes
map_missing_values <- function(x) {
  if (is.numeric(x)) {
    x <- ifelse(x >= -999 & x <= -1, recode_missing_values(x), x)
  }
  return(x)
}

# Recode missing values to standard scheme
recode_missing_values <- function(x) {
  x <- ifelse(
