      # For sweeps 2-4, 6-7, use ever_var
      if (age %in% c(15, 16, 17, 19, 20)) {
        df <- df %>%
          mutate(`drinking_${age}` = ifelse(`{{ever_var}}` == 1, 1, NA_real_))
      }
      # For sweeps 8-9, use AUDIT frequency (above 'Never')
      if (age %in% c(25, 32)) {
        df <- df %>%
          mutate(`drinking_${age}` = ifelse(`{{ever_var}}` > 1, 1, NA_real_))
      }
    }
  }

  return(df)
