derive_alcfst <- function(df) {
  ages <- c(14, 15, 16, 17, 19, 20, 25, 32)
  drinking_vars <- paste0('drinking_', ages)

  # Check which drinking variables are available
  available_vars <- drinking_vars[df %>% select(all_of(drinking_vars)) %>% select_if(any_vars) %>% names()]

  # Initialize alcfst with NA
  df <- df %>%
    mutate(alcfst = NA_integer_)

  # Determine earliest age of drinking
  for (age in ages) {
    var_name <- paste0('drinking_', age)
    if (var_name %in% available_vars) {
      df <- df %>%
        mutate(alcfst = ifelse(
          is.na(alcfst) & !is.na(`{{var_name}}`) & `{{var_name}}` == 1,
          age,
          alcfst
        ))
    }
  }

  # Handle cases where no drinking is observed
  df <- df %>%
    mutate(
      alcfst = ifelse(
        is.na(alcfst) & !any(sapply(drinking_vars, function(x) !is.na(df[[x]]) & df[[x]] == 1)),
        ifelse(all(sapply(drinking_vars, function(x) !is.na(df[[x]]))), 99, -8),
        alcfst
      )
    )

