recode <- function(x) {
  if (!is.numeric(x)) return(x)
  x[is.na(x)] <- -3
  x[x == -999 | x == -998 | x == -997 | x == -995] <- -2
  x[x == -99] <- -3
  x[x == -97 | x == -96] <- -2
  x[x == -92] <- -9
  x[x == -91] <- -1
  x[x == -1] <- -8
